'use strict';
const $=id=>document.getElementById(id),reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
const portrait=(slug,alt)=>'<img src="../../assets/showdown/trainers/'+slug+'.png" alt="'+alt+'">';
const duoArt=['jessie','james'].map(name=>'<span class="sheet"><img src="../../assets/rocket-duo/'+name+'-color.png" alt="'+name+'"></span>').join('');
const scenes={
 officer:{kind:'ENCONTRO / OFICIAL ROCKET',heading:'Passagem bloqueada',speaker:'ARCHER',location:'Setor de contenção',art:portrait('archer','Archer'),reward:'<span>Vitória <b>+9 ouro</b></span><span><b>+2 XP</b></span><span><b>1 equipamento</b></span>',pages:['Então foi você que desligou as câmeras... Eu estava esperando alguém mais discreto.','Este corredor está sob meu comando. Organize seus Pokémon — se quiser passar, vai ter que me vencer.'],choices:[['Preparar equipe','Organizar antes da batalha','Sua equipe está em preparação. Este protótipo não inicia uma partida real.'],['Ver o adversário','7 Pokémon · equipe reforçada','Archer trouxe uma equipe reforçada. Procure proteger seus atacantes com uma linha de frente.'],['Salvar e sair','Continuar esta tentativa depois','No jogo, esta opção guardará a tentativa. Aqui você pode explorar os outros exemplos.']]},
 duo:{kind:'ENCONTRO ESPECIAL / JESSIE E JAMES',heading:'Encrenca em dobro',speaker:'JESSIE E JAMES',location:'Depósito Rocket',art:duoArt,reward:'<span>Vitória <b>+6 ouro · +2 XP</b></span><span>Derrota <b>risco de roubo</b></span>',pages:['Jessie: Prepare-se para encrenca!\nJames: E para encrenca em dobro!','Jessie: Esses Pokémon parecem muito bem cuidados...\nJames: E essa mochila também! Vamos resolver isso numa batalha!'],choices:[['Preparar equipe','Vença para abrir a passagem','A dupla prepara Ekans, Koffing e Meowth. Sua equipe poderá ser organizada antes da luta.'],['Sobre a revanche','Recupere o que foi roubado','Em uma derrota, a dupla pode roubar ouro ou um item da mochila. Vencer a revanche devolve o saque.'],['Salvar e sair','Retomar o encontro depois','A revanche e o saque ficam guardados na tentativa. Nenhum dado real é alterado neste protótipo.']]},
 rescue:{kind:'RESGATE / POKÉMON LIBERTADO',heading:'A cela está aberta',speaker:'EQUIPE DE RESGATE',location:'Setor de contenção',art:'<img class="mon" src="../../assets/pokeapi/sprites/pokemon/104.png" alt="Cubone">',reward:'<span>Encontrado <b>Cubone</b></span><span><b>★ · Terra</b></span>',pages:['Cubone segura seu osso com força e se aproxima devagar. Os guardas já não estão por perto.','Você pode levá-lo para a equipe ou encaminhá-lo para segurança. Um Pokémon protegido também conta como resgate.'],choices:[['Levar para a equipe','Ocupa uma vaga no banco','Cubone seguirá com sua equipe. No jogo, é necessário ter uma vaga no banco.'],['Encaminhar para segurança','+1 resgate · não ocupa espaço','Cubone foi encaminhado para um lugar seguro. A operação pode continuar.'],['Abrir a reserva','+1 equipamento · +1 alerta','A reserva contém um equipamento, mas o barulho chama a atenção dos guardas. Depois, você escolhe o destino de Cubone.']]},
 terminal:{kind:'EXPLORAÇÃO / TERMINAL',heading:'Acesso à segurança',speaker:'SISTEMA ROCKET',location:'Central de comando',art:'<img src="../../assets/mode-art/rocket-terminal.svg" alt="Terminal de segurança">',reward:'<span>Encontro <b>sem combate</b></span><span>Alerta atual <b>2 / 4</b></span>',pages:['TERMINAL R-04\nCredencial aceita. Controles de vigilância disponíveis.','Selecione uma operação. Você pode desligar as câmeras ou localizar um depósito de suprimentos.'],choices:[['Desativar câmeras','−2 alerta','Câmeras desativadas. Sua equipe pode atravessar o próximo corredor com mais discrição.'],['Localizar depósito','Escolher 1 equipamento','Um depósito foi localizado. No jogo, você poderá escolher um equipamento para a mochila.'],['Salvar e sair','Decidir depois','O encontro ficará disponível ao retomar a tentativa.']]},
 victory:{kind:'RESULTADO / PASSAGEM LIBERADA',heading:'A dupla está decolando!',speaker:'JAMES',location:'Depósito Rocket',art:duoArt,reward:'<span>Recebido <b>+6 ouro · +2 XP</b></span><span>Revanche <b>saque recuperado</b></span>',pages:['Como é que a gente foi perder de novo?! Jessie, acho melhor devolver essa mochila...','Jessie: Isso ainda não acabou!\nA Equipe Rocket está decolando de novo!'],choices:[['Continuar operação','Escolher o próximo caminho','A passagem está livre. Seu próximo destino aparece no mapa da infiltração.'],['Salvar e sair','Continuar a jornada depois','A vitória e os recursos recuperados serão mantidos quando este fluxo for integrado ao jogo.']]}
};
for(const [id,scene] of Object.entries(window.ROCKET_DIALOGUE_SCENES||{})){if(scene.art==='DUO')scene.art=duoArt;scenes[id]=scene;const option=document.createElement('option');option.value=id;option.textContent=scene.label;$('stage-select').append(option)}
$('stage-select').onchange=()=>{if($('stage-select').value)show($('stage-select').value)};
let current='officer',page=0,selected=0,typing=null,fullText='',displayed='',note=null;
function stop(){clearInterval(typing);typing=null}
function write(text){stop();fullText=text;displayed='';$('text').textContent='';if(reduced){displayed=text;$('text').textContent=text;return}typing=setInterval(()=>{displayed=fullText.slice(0,displayed.length+1);$('text').textContent=displayed;if(displayed.length%3===0&&/\S/.test(displayed.slice(-1)))DIALOGUE_FX.play('type');if(displayed.length===fullText.length)stop()},23)}
function finish(){stop();displayed=fullText;$('text').textContent=fullText}
function choose(index,sound=true){const previous=selected;selected=(index+scenes[current].choices.length)%scenes[current].choices.length;if(sound&&previous!==selected)DIALOGUE_FX.play('select');[...$('choices').children].forEach((button,i)=>{button.classList.toggle('selected',i===selected);button.setAttribute('aria-current',String(i===selected))})}
function confirm(index){if(typing){DIALOGUE_FX.play('advance');finish();return}DIALOGUE_FX.play('confirm');choose(index,false);note=scenes[current].choices[selected][2];$('page').textContent='PRÉVIA DA ESCOLHA';write(note);$('feedback').textContent='Demonstração · clique no diálogo para voltar à conversa'}
function advance(){DIALOGUE_FX.play('advance');if(typing){finish();return}if(note){note=null;page=0}else if(page<scenes[current].pages.length-1)page++;else{$('choices').children[selected]?.focus();return}renderText()}
function renderText(){$('page').textContent='DIÁLOGO '+(page+1)+' / '+scenes[current].pages.length;write(scenes[current].pages[page])}
function show(id){DIALOGUE_FX.play('confirm');$('stage-select').value=window.ROCKET_DIALOGUE_SCENES?.[id]?id:'';current=id;page=0;selected=0;note=null;document.body.classList.remove('peek');$('peek').setAttribute('aria-pressed','false');$('peek').innerHTML='◉ Ver tabuleiro <kbd>V</kbd>';const scene=scenes[id];for(const field of ['kind','heading','speaker','location'])$(field).textContent=scene[field];$('character').innerHTML=scene.art;$('reward').innerHTML=scene.reward;$('choices').replaceChildren();scene.choices.forEach(([label,hint],i)=>{const button=document.createElement('button');button.type='button';const text=document.createElement('span'),small=document.createElement('small');text.textContent=label;small.textContent=hint;button.append(text,small);button.onmouseenter=()=>choose(i);button.onfocus=()=>choose(i);button.onclick=()=>confirm(i);$('choices').append(button)});document.querySelectorAll('[data-scene]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.scene===id)));$('feedback').textContent='Protótipo independente · não altera sua partida';choose(0,false);renderText()}
document.querySelectorAll('[data-scene]').forEach(button=>button.onclick=()=>show(button.dataset.scene));$('advance').onclick=advance;
$('peek').onclick=()=>{const open=document.body.classList.toggle('peek');$('peek').setAttribute('aria-pressed',String(open));$('peek').innerHTML=open?'◉ Voltar ao diálogo <kbd>V</kbd>':'◉ Ver tabuleiro <kbd>V</kbd>'};
addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.tagName==='SELECT')return;if(e.key.toLowerCase()==='v'){e.preventDefault();$('peek').click();return}if(document.body.classList.contains('peek'))return;if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();choose(selected+(e.key==='ArrowUp'?-1:1));$('choices').children[selected]?.focus()}else if(e.key===' '){e.preventDefault();advance()}else if(e.key==='Enter'&&!e.repeat){if(e.target.closest('.prototype,#sound,#effects,#peek'))return;e.preventDefault();confirm(selected)}});
$('sound').onclick=async()=>{const music=$('music');if(!music.paused){music.pause();$('sound').textContent='♫ Música desligada';$('sound').setAttribute('aria-pressed','false');return}music.volume=.18;try{await music.play();$('sound').textContent='♫ Silenciar música';$('sound').setAttribute('aria-pressed','true')}catch{$('feedback').textContent='Clique novamente para iniciar a música.'}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){finish();$('music').pause();$('sound').textContent='♫ Música desligada';$('sound').setAttribute('aria-pressed','false')}});
show('officer');
